import {jobs,photos,tasks,requests,materialLines,jobById,laborRate} from './data.js';

const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2,minimumFractionDigits:v%1?2:0}).format(v);
const paths={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-8h6v8"/>',work:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4h8v3M3 12h18M10 12v3h4v-3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18M7 14h3m4 0h3M7 17h3"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16M15 5v16"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',photo:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="2"/><path d="m21 15-6-6L3 21"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4m1-17a3 3 0 0 1 0 6m2 5c3 0 4 2 4 5"/>',box:'<path d="m3 6 9-4 9 4v13l-9 4-9-4zM3 6l9 5 9-5M12 11v12M7 4l10 5"/>',file:'<path d="M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h8"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m15 5-7 7 7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',check:'<path d="m5 12 4 4L20 5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',minus:'<path d="M4 12h16"/>',bell:'<path d="M5 16h14l-2-4V8a5 5 0 0 0-10 0v4zM10 20h4"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',play:'<path d="m8 4 12 8-12 8z"/>',message:'<path d="M21 15a3 3 0 0 1-3 3H8l-5 4V5a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3zM7 7h10M7 11h7"/>',clip:'<path d="m8 13 7-7a3 3 0 0 1 4 4L9 20a5 5 0 0 1-7-7L13 2"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/>',receipt:'<path d="M5 2 8 4l4-2 4 2 3-2v20l-3-2-4 2-4-2-3 2zM8 8h8M8 12h8M8 16h5"/>',chart:'<path d="M3 3v18h19M7 17v-5m5 5V8m5 9V4"/>',leaf:'<path d="M20 3C9 1 2 6 4 14s15 8 16-11ZM4 20 16 8"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>',phone:'<path d="M5 2h4l2 5-3 2c1 3 3 5 6 6l2-3 5 2v4c0 3-4 4-7 2C8 18 2 12 2 6c0-2 1-4 3-4Z"/>',send:'<path d="m22 2-7 20-4-9-9-4zM11 13 22 2"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h10a4 4 0 0 1 0 8H7a3 3 0 0 0 0 6h10"/>',plan:'<path d="M3 3h18v18H3zM3 9h9V3m0 9v9m0-6h9M6 9v6h3"/>',shield:'<path d="m12 2 9 4v7c0 5-9 9-9 9S3 18 3 13V6zM8 12l3 3 5-6"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.file}</svg>`;
const img=(f,alt,cls='',eager=false)=>`<img src="assets/${f}.jpg" alt="${esc(alt)}" class="${cls}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;
const btn=(text,action,cls='',ic='arrow')=>`<button class="btn ${cls}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
const badge=s=>`<span class="badge ${({'In progress':'progress','Punch list':'punch','Scheduled':'scheduled','Completed':'complete'}[s]||'neutral')}">${esc(s)}</span>`;
const navs=[['home','home','Overview'],['jobs','work','Open work'],['schedule','calendar','Schedule'],['map','map','Job map'],['photos','photo','Photo library'],['contacts','users','Contacts'],['materials','box','Materials'],['forms','file','Forms & files'],['hours','clock','Hours'],['team','users','Team']];
const state={role:'owner',page:'home',job:null,tab:'overview',filter:'All jobs',view:'grid',photoFilter:'All photos',taskFilter:'All tasks',period:'Week',week:0,zoom:1};
let gallery=[],galleryIndex=0,toastTimer,lastFocus;
const visibleJobs=()=>jobs.filter(j=>state.role==='owner'||!j.service||j.crew.includes('Eli'));
const visibleIds=()=>new Set(visibleJobs().map(j=>j.id));
const visiblePhotos=()=>photos.filter(p=>visibleIds().has(p.job));
const jobPhotos=id=>photos.filter(p=>p.job===id);
const jobTasks=id=>tasks.filter(t=>t.job===id);
const heading=(eyebrow,title,sub='',actions='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;
const panel=(title,body,ic='file')=>`<section class="panel panel-pad"><h3 class="panel-title">${icon(ic)}${title}</h3>${body}</section>`;
const callout=(body,ic='info')=>`<div class="callout">${icon(ic)}<p>${body}</p></div>`;
const photoNote='<p class="image-note">Illustrative sample images · AI-generated plumbing scenes and Unsplash stock · These are not records of Heirloom’s work.</p>';
const avatars=j=>`<div class="mini-avatars">${j.crew.map(n=>`<span title="${esc(n)} · sample crew">${n[0]}</span>`).join('')}</div>`;
function card(j){return `<button class="job-card" data-action="job:${j.id}"><div class="image-wrap">${img(j.cover,`${j.title} · illustrative sample photo`)}<span class="card-status">${badge(j.status)}</span><span class="photo-count">${icon('photo')}${jobPhotos(j.id).length} sample photos</span></div><div class="job-card-copy"><small>${j.id} &nbsp;·&nbsp; ${j.type}</small><h3>${j.title}</h3><p>${icon('pin')}${j.town}, SC &nbsp;·&nbsp; ${j.customer}</p></div><div class="job-card-foot"><span>${j.status==='Completed'?'Completed Oct 27':j.date==='2026-10-29'?`Today · ${j.time}`:j.date==='2026-10-30'?`Fri · ${j.time}`:`Mon · ${j.time}`}</span>${avatars(j)}</div></button>`;}
function taskRow(t){return `<button class="task-row" data-action="task:${t.id}"><span class="task-circle ${t.status==='Completed'?'done':''}">${t.status==='Completed'?icon('check'):''}</span><span class="task-copy"><strong>${t.title}</strong><small>${t.who} · ${t.when}</small></span>${img(t.photo,'Illustrative task photo','task-thumb')}${badge(t.status)}</button>`;}
function photoTile(p){return `<button class="photo-tile" data-action="photo:${p.id}">${img(p.file,p.caption+' · illustrative sample')}<span class="photo-tag">${p.stage}</span><span class="sample-ribbon">SAMPLE</span><div class="photo-tile-copy"><h3>${p.caption}</h3><p>${jobById(p.job).title} · ${p.date}</p></div></button>`;}
function render(){
 const active=state.page==='job'?'jobs':state.page;
 const pageName=state.page==='job'?jobById(state.job)?.title:(navs.find(n=>n[0]===state.page)?.[2]||'Your workspace');
 document.title=`${pageName} · Heirloom Demo`;
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><button class="brand" data-action="nav:home" aria-label="Heirloom Plumbing home"><img src="assets/brand-logo.png" alt="Heirloom Plumbing LLC"><span><strong>Heirloom</strong><small>PLUMBING LLC</small></span></button><div class="side-label">YOUR WORKSPACE</div><nav class="nav" aria-label="Main navigation">${navs.map(([id,ic,title])=>`<button data-action="nav:${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ic)}${title}${id==='jobs'?`<span class="nav-count">${visibleJobs().filter(j=>j.status!=='Completed').length}</span>`:id==='materials'?'<span class="nav-count">2</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><p class="side-message">Generational<br>quality.</p><button class="powered" data-action="nav:ready">${icon('leaf')}<span>Built with <strong>Everbranch</strong></span></button></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><span>Heirloom Plumbing</span>${icon('chevron')}<strong>${esc(pageName)}</strong></div><div class="top-actions"><form class="search-box" id="search-form" role="search">${icon('search')}<input aria-label="Search sample jobs" name="query" placeholder="Search jobs, customers…" autocomplete="off"></form><select id="role" class="role-select" aria-label="Preview role"><option value="owner" ${state.role==='owner'?'selected':''}>Owner · Garth</option><option value="field" ${state.role==='field'?'selected':''}>Field · Eli</option></select><button class="icon-btn" data-action="activity" aria-label="View sample activity">${icon('bell')}</button><div class="avatar" title="${state.role==='owner'?'Garth · owner preview':'Eli · fictional field person'}">${state.role==='owner'?'G':'E'}</div></div></header><div class="demo-strip">${icon('lock')}<strong>BROWSE-ONLY DEMO</strong><span class="strip-detail">Fictional jobs, people & photos. Nothing can be created or sent.</span><button data-action="tour">Take a quick tour ${icon('arrow')}</button></div><main class="page" id="content" tabindex="-1">${renderPage()}<footer class="footer"><span>Heirloom Plumbing LLC · Everbranch Field demo<br>Sample workspace · Demo day: Thursday, October 29, 2026</span><button data-action="nav:ready">What happens when you’re ready?</button></footer></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${[['home','home','Home'],['jobs','work','Work'],['schedule','calendar','Schedule'],['photos','photo','Photos'],['more','more','More']].map(([id,ic,n])=>`<button data-action="${id==='more'?'more':'nav:'+id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ic)}${n}</button>`).join('')}</nav></div>`;
 $('#role').addEventListener('change',e=>{state.role=e.target.value;closeModal();if(state.role==='field'&&state.tab==='financials')state.tab='overview';if(state.job&&!visibleJobs().some(j=>j.id===state.job)){state.page='jobs';state.job=null;}render();toast(state.role==='field'?'Field preview: Eli’s time, shared projects and assigned service calls.':'Owner preview: job costs, customers and the whole team.');});
 $('#search-form').addEventListener('submit',e=>{e.preventDefault();search(new FormData(e.target).get('query'));});
 if(state.page==='job'&&state.tab==='plans')applyZoom();
}
function renderPage(){switch(state.page){case'jobs':return work();case'job':return jobDetail();case'schedule':return schedule();case'map':return mapPage();case'photos':return photoPage();case'contacts':return contacts();case'materials':return materials();case'forms':return forms();case'hours':return hours();case'team':return team();case'ready':return ready();default:return home();}}
function home(){
 const open=visibleJobs().filter(j=>j.status!=='Completed'),today=open.filter(j=>j.date==='2026-10-29');
 return `<section class="hero">${img('bathroom','Illustrative sample bathroom · Unsplash stock','',true)}<div class="hero-copy"><div class="eyebrow">HEIRLOOM PLUMBING &nbsp;/&nbsp; YOUR WORK, CONNECTED</div><h1>Welcome, ${state.role==='owner'?'Garth':'Eli'}.<br>Let’s build a good day.</h1><p>${state.role==='owner'?'Every job. Every detail. All in one place.<br>Here’s what’s happening with your work.':'Your work, your photos, your next stop.<br>Everything you need for the day ahead.'}</p>${btn('Explore your open work','nav:jobs','','arrow')}</div><div class="hero-stamp">${icon('shield')}GENERATIONAL QUALITY</div></section><div class="metrics">${[[open.length,'Open jobs','Ready to explore','work','nav:jobs'],[today.length,'On the schedule','Demo day · Oct 29','calendar','nav:schedule'],[visiblePhotos().length,'Job photos','A record of the work','photo','nav:photos'],[2,'Materials requested','Sample requests','box','nav:materials']].map(([n,title,sub,ic,a])=>`<button class="metric" data-action="${a}"><span>${title}</span>${icon(ic)}<strong>${n}</strong><small>${sub}</small></button>`).join('')}</div><div class="dash-grid"><section><div class="section-head"><h2>Your open work <small>${open.length} jobs</small></h2><button class="text-btn" data-action="nav:jobs">View all work ${icon('arrow')}</button></div><div class="job-grid">${open.slice(0,4).map(card).join('')}</div></section><aside class="dash-aside"><section class="panel panel-pad"><h3 class="panel-title">${icon('calendar')}Today’s plan <span class="label" style="margin:0 0 0 auto;font-size:7px">OCT 29</span></h3>${today.map(j=>`<div class="timeline-row"><span class="timeline-dot"></span><button class="timeline-content" data-action="job:${j.id}"><small>${j.time} · ${j.town}</small><h4>${j.title.split(' · ')[1]}</h4><p>${j.crew.join(' & ')} · ${j.phase}</p></button></div>`).join('')}<button class="text-btn" data-action="nav:schedule">Open schedule ${icon('arrow')}</button></section><div class="aside-note">${icon('plan')}<h3>The details stay with the job.</h3><p>Plans, photos, tasks and conversations. Open Oakridge to see how it all connects.</p><button class="text-btn" data-action="job:HP-104:plans">Explore plan pins ${icon('arrow')}</button></div></aside></div><div class="quick-links">${[['plan','Plans & punch lists','See what goes where','job:HP-104:plans'],['receipt','Receipts to materials','Keep the source photo','receipt:HP-104'],['file','Forms & files','Keep a clear job record','nav:forms'],[state.role==='owner'?'chart':'clock',state.role==='owner'?'Job profitability':'My hours',state.role==='owner'?'Understand the numbers':'See your sample week',state.role==='owner'?'job:HP-104:financials':'nav:hours']].map(([ic,t,s,a])=>`<button class="quick-link" data-action="${a}">${icon(ic)}<span><strong>${t}</strong><small>${s}</small></span></button>`).join('')}</div>`;
}
function work(){
 const groups=['All jobs','In progress','Scheduled','Punch list','Completed'];let list=visibleJobs().filter(j=>state.filter==='All jobs'||j.status===state.filter);
 return heading('THE WORK, ALL TOGETHER','Open work','Explore a job to see its plans, photos, notes and materials.',btn('New job','locked:new job','','plus'))+`<div class="filters">${groups.map(g=>`<button class="chip ${state.filter===g?'active':''}" data-action="filter:${g}">${g} <small> ${visibleJobs().filter(j=>g==='All jobs'||j.status===g).length}</small></button>`).join('')}<span class="filter-spacer"></span><div class="view-toggle" aria-label="Job display">${['grid','list'].map(v=>`<button class="${state.view===v?'active':''}" data-action="view:${v}" aria-label="${v} view">${icon(v)}</button>`).join('')}</div></div>${state.role==='field'?callout('<strong>Field preview · Eli.</strong> Shared projects are browsable. One-day service calls appear only when assigned to Eli. Job costs and private customer details are reserved for the owner.','shield'):''}<div class="${state.view==='grid'?'job-grid':'job-list'}">${list.length?list.map(card).join(''):'<div class="empty">No sample jobs in this view.<br>Choose another status to keep exploring.</div>'}</div>`;
}
function jobDetail(){
 const j=jobById(state.job);if(!j||!visibleIds().has(j.id))return '<div class="empty">This job is unavailable in the selected role.</div>';
 const tabs=[['overview','Overview'],['tasks','To-dos'],['plans','Plans & pins'],['photos','Photos'],['materials','Materials'],['notes','Conversation'],['forms','Forms & files'],...(state.role==='owner'?[['financials','Job costs']]:[])];
 return `<button class="back-btn" data-action="nav:jobs">${icon('back')}All work</button><section class="hero detail-hero">${img(j.cover,j.title+' · sample photo','',true)}<div class="hero-copy"><div class="eyebrow">${j.id} &nbsp; / &nbsp; ${j.type.toUpperCase()} &nbsp; / &nbsp; SAMPLE JOB</div><h1>${j.title}</h1><p>${j.customer} · ${j.town}, SC</p>${badge(j.status)}</div><span class="hero-stamp">${icon('photo')}ILLUSTRATIVE SAMPLE</span></section><div class="detail-toolbar"><div class="detail-meta"><span>${icon('calendar')}${j.date==='2026-10-29'?'Today':j.date==='2026-10-30'?'Friday':j.date==='2026-11-02'?'Mon, Nov 2':'Oct 27'} · ${j.time}</span><span>${icon('users')}${j.crew.join(' & ')}</span><span>${icon('photo')}${jobPhotos(j.id).length} photos</span></div>${btn('Route preview','route:'+j.id,'small','route')}</div><div class="tabs" role="navigation" aria-label="Job sections">${tabs.map(([id,n])=>`<button data-action="tab:${id}" class="${state.tab===id?'active':''}" ${state.tab===id?'aria-current="page"':''}>${n}${id==='tasks'?` (${jobTasks(j.id).length})`:id==='photos'?` (${jobPhotos(j.id).length})`:''}</button>`).join('')}</div>${({overview:()=>overview(j),tasks:()=>taskPage(j),plans:()=>planPage(j),photos:()=>photoPage(j),materials:()=>materials(j),notes:()=>notes(j),forms:()=>forms(j),financials:()=>financials(j)}[state.tab]||(()=>overview(j)))()}`;
}
function overview(j){return `<div class="two-col"><div class="stack">${panel('The work',`<p class="body-copy">${j.description}</p><div class="progress-bar"><span style="width:${j.percent}%"></span></div><div class="progress-labels"><span>${j.phase}</span><span>${j.percent}% · sample progress</span></div>`,'work')}${panel('Up next',jobTasks(j.id).slice(0,3).map(taskRow).join('')+`<button class="text-btn" data-action="tab:tasks">All to-dos ${icon('arrow')}</button>`,'check')}${panel('A visual record',photoNote+`<div class="photo-strip">${jobPhotos(j.id).slice(0,3).map(p=>`<button data-action="photo:${p.id}" aria-label="Open ${esc(p.caption)}">${img(p.file,p.caption+' · sample')}</button>`).join('')}</div><button class="text-btn" style="margin-top:12px" data-action="tab:photos">View job photos ${icon('arrow')}</button>`,'photo')}</div><div class="stack">${panel('Job essentials',`<div class="info-row"><span class="label">LOCATION · FICTIONAL ADDRESS</span><strong>${j.address}</strong><p>${j.town}, South Carolina</p></div><div class="info-row"><span class="label">ACCESS NOTES · SAMPLE</span><strong>${j.access}</strong></div><div class="info-row"><span class="label">BUILDER / SITE LEAD</span><strong>${j.builder}</strong></div>${state.role==='owner'?`<div class="info-row"><span class="label">CUSTOMER CONTACT · FICTIONAL</span><strong>${j.contact}</strong><p>${j.phone}<br>${j.email}</p></div>`:`<div class="info-row"><span class="label">CUSTOMER CONTACT</span><p>Private details are reserved for the owner preview.</p></div>`}`,'pin')}${panel('Remember this',`<p class="body-copy">${j.note}</p><button class="text-btn" style="margin-top:12px" data-action="tab:notes">Open job conversation ${icon('arrow')}</button>`,'message')}${state.role==='owner'?panel('See the whole picture',`<p class="body-copy">The sample quote, materials and labor stay together, so you can see what’s left.</p><button class="text-btn" style="margin-top:12px" data-action="tab:financials">Explore job costs ${icon('arrow')}</button>`,'chart'):panel('Your time on this job',`<p class="body-copy">Sample hours are visible in My Hours. Clocking in and out is locked in this demo.</p><button class="text-btn" data-action="nav:hours">Open My Hours ${icon('arrow')}</button>`,'clock')}</div></div>`;}
function taskPage(j){const ts=jobTasks(j.id).filter(t=>state.taskFilter==='All tasks'||t.status===state.taskFilter);return `<div class="section-head"><div><h2>The next right thing.</h2><p>Scheduled work, active tasks and punch items, with their history.</p></div>${btn('Add to-do','locked:to-do','small','plus')}</div><div class="filters">${['All tasks','Scheduled','In progress','Punch list','Completed'].map(s=>`<button class="chip ${state.taskFilter===s?'active':''}" data-action="taskfilter:${s}">${s}</button>`).join('')}</div><section class="panel panel-pad">${ts.length?ts.map(taskRow).join(''):'<p class="body-copy">No sample tasks in this status. Choose another filter.</p>'}</section>`;}
function floorPlan(){return `<svg class="floor-plan" viewBox="0 0 620 496" aria-label="Illustrative bathroom floor plan. Use the numbered buttons to explore task pins."><defs><pattern id="plan-grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#f0f1e9" stroke-width=".6"/></pattern></defs><rect width="620" height="496" fill="url(#plan-grid)"/><g fill="none" stroke="#798d75" stroke-width="2"><path d="M95 75H525V410H340M260 410H95V75" stroke-width="7"/><path d="M340 410V330a80 80 0 0 0-80 80" stroke-width="1.2"/><path d="M385 75V220H525M95 210h180V75"/><rect x="115" y="95" width="140" height="70" rx="3"/><ellipse cx="155" cy="130" rx="22" ry="17"/><ellipse cx="217" cy="130" rx="22" ry="17"/><path d="M155 103v12m62-12v12"/><path d="M405 95h100v100H405zM405 95l100 100m-100 0L505 95" stroke="#b8c3ae"/><rect x="450" y="270" width="48" height="70" rx="20"/><rect x="447" y="254" width="54" height="22" rx="3"/><path d="M75 75V410m-7-335h14m-14 335h14M95 53H525m-430-7v14m430-14v14" stroke="#c3cbb8" stroke-width="1"/></g><g font-family="sans-serif" fill="#8c9a7f" font-size="10" text-anchor="middle"><text x="310" y="42">14′–0″ · ILLUSTRATIVE</text><text x="59" y="245" transform="rotate(-90 59 245)">11′–0″ · SAMPLE ONLY</text><text x="185" y="191" font-size="9">DOUBLE VANITY</text><text x="455" y="209" font-size="9">SHOWER</text><text x="310" y="280" font-family="Georgia" font-size="20" fill="#586f4d">Primary bath</text><text x="310" y="300" font-size="8">DEMO LAYOUT · NOT FOR CONSTRUCTION</text><text x="310" y="465" font-size="8">ILLUSTRATIVE PLAN · REVISION B · NO TECHNICAL AUTHORITY</text></g></svg>`;}
function planPage(j){return `<div class="section-head"><div><h2>A place for every detail.</h2><p>Open a numbered pin to see the task, photo and conversation.</p></div>${btn('Upload plan','locked:plan upload','small','plus')}</div>${callout('<strong>Plan interaction preview.</strong> Click existing pins and zoom the example drawing. Pin placement, uploads and status changes are locked. This diagram is illustrative and is not a construction plan.','plan')}<div class="plan-layout"><section class="plan-board"><div class="plan-top">${icon('file')}Bath layout · Revision B <small>SAMPLE DRAWING</small><div class="plan-tools"><button class="icon-btn" data-action="zoom:-1" aria-label="Zoom out">${icon('minus')}</button><button class="icon-btn" data-action="zoom:1" aria-label="Zoom in">${icon('plus')}</button></div></div><div class="plan-canvas"><div class="plan-drawing" id="plan-drawing">${floorPlan()}${jobTasks(j.id).map((t,i)=>`<button class="plan-pin ${t.status==='Punch list'?'punch':''}" style="left:${t.pin[0]}%;top:${t.pin[1]}%" data-action="task:${t.id}" aria-label="Pin ${i+1}: ${t.title}">${i+1}</button>`).join('')}</div></div><div class="plan-key"><span class="dot"></span>Task pins <span class="dot" style="background:#b08458;margin-left:10px"></span>Punch item <span style="margin-left:auto">Tap a pin to explore</span></div></section><section class="panel panel-pad"><h3 class="panel-title">${icon('pin')}Pinned to this plan</h3><div class="plan-task-list">${jobTasks(j.id).map(taskRow).join('')}</div></section></div>`;}
function applyZoom(){const p=$('#plan-drawing');if(p){p.style.transform=`scale(${state.zoom})`;p.style.transformOrigin=state.zoom>1?'top left':'center';}}
function photoPage(j){const pool=j?jobPhotos(j.id):visiblePhotos(),list=pool.filter(p=>state.photoFilter==='All photos'||p.stage===state.photoFilter);return `${j?'':heading('THE WORK SPEAKS','Photo library','Before, progress and after. A clear record, kept with every job.',btn('Add photos','locked:photo upload','','plus'))}${j?'<div class="section-head"><h2>The story of this job.</h2>'+btn('Add photos','locked:photo upload','small','plus')+'</div>':''}${photoNote}<div class="filters">${['All photos','Before','Progress','After','Reference'].map(s=>`<button class="chip ${state.photoFilter===s?'active':''}" data-action="photofilter:${s}">${s} <small>${pool.filter(p=>s==='All photos'||p.stage===s).length}</small></button>`).join('')}</div><div class="photo-grid">${list.length?list.map(photoTile).join(''):'<div class="empty">No sample photos in this category.<br>Try All photos.</div>'}</div>`;}
function materials(j){const reqs=requests.filter(r=>!j||r.job===j.id);return `${j?'':heading('NOTHING FALLS THROUGH THE CRACKS','Materials & receipts','See what the job needs, what was purchased, and where it came from.',btn('New request','locked:material request','','plus'))}${callout('<strong>From photo to job cost.</strong> Explore a prefilled receipt example and its material lines. Scanning, uploading, ordering and QuickBooks export are locked in this demo.','receipt')}<div class="two-col"><div class="stack">${panel('Materials requested',reqs.length?reqs.map(r=>`<div class="request-row">${img(r.photo,'Sample material reference')}<div><strong>${r.title}</strong><small>${r.qty} · ${r.who} · ${jobById(r.job).title}</small></div>${badge(r.status)}</div>`).join(''):'<p class="body-copy">No material requests for this sample job.</p>','box')}${j&&j.id==='HP-104'?materialTable(j):panel('Job material records',visibleJobs().filter(x=>x.materials&&(!j||j.id===x.id)).map(x=>`<button class="task-row" data-action="${j?'receipt:'+x.id:'job:'+x.id+':materials'}"><span class="task-circle">${icon('receipt')}</span><span class="task-copy"><strong>${x.title}</strong><small>${x.id} · Sample material record</small></span>${state.role==='owner'?`<strong style="font-size:12px">${money(x.materials)}</strong>`:icon('chevron')}</button>`).join('')||'<p class="body-copy">Materials have not been recorded for this sample job.</p>','receipt')}</div><div class="stack">${panel('Keep the original',`<p class="body-copy">A receipt or shelf-label photo stays linked to the material entry. Review the extracted lines before using them.</p><button class="receipt-card" data-action="receipt:${j?.id||'HP-104'}"><span class="receipt-paper">${'<i></i>'.repeat(6)}</span><div><strong>Explore a receipt example</strong><small>Sample Supply Co. · Oct 29<br>Prefilled extraction · no scanner connected</small></div>${icon('chevron')}</button>`,'receipt')}${panel('QuickBooks',`<span class="badge neutral">Not connected</span><p class="body-copy" style="margin-top:12px">Your current invoicing stays in QuickBooks. The live workflow can be planned around approved imports and reviewed exports.</p><button class="text-btn" style="margin-top:12px" data-action="nav:ready">See the launch path ${icon('arrow')}</button>`,'chart')}</div></div>`;}
function materialTable(j){return `<section class="panel"><div class="panel-pad" style="padding-bottom:0"><h3 class="panel-title">${icon('box')}Sample materials · ${j.id}</h3></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Material</th><th>Qty</th>${state.role==='owner'?'<th class="money">Unit cost</th><th class="money">Total</th>':''}</tr></thead><tbody>${materialLines.map(l=>`<tr><td><strong>${l.name}</strong></td><td>${l.qty}</td>${state.role==='owner'?`<td class="money">${money(l.unit)}</td><td class="money">${money(l.qty*l.unit)}</td>`:''}</tr>`).join('')}${state.role==='owner'?`<tr class="table-total"><td colspan="3">Recorded sample materials</td><td class="money">${money(j.materials)}</td></tr>`:''}</tbody></table></div><div class="panel-pad">${btn('View source receipt','receipt:'+j.id,'small','receipt')}</div></section>`;}
function notes(j){const ps=jobPhotos(j.id);return `<div class="two-col"><section class="panel"><div class="panel-pad"><h3 class="panel-title">${icon('message')}Job conversation <span class="badge neutral" style="margin-left:auto">Sample thread</span></h3><div class="message"><div class="avatar">G</div><div class="message-body"><div class="message-head"><strong>Garth</strong><small>Today · 8:15 AM · sample</small></div><p>Morning walk-through complete.\n\n${j.note}\n\nLet’s keep the progress photos in this thread so we can find them later.</p><div class="message-photos">${ps.slice(0,2).map(p=>`<button data-action="photo:${p.id}" aria-label="Open sample photo ${esc(p.caption)}">${img(p.file,p.caption+' · illustrative')}</button>`).join('')}</div></div></div><div class="message"><div class="avatar">E</div><div class="message-body"><div class="message-head"><strong>Eli · sample crew</strong><small>Today · 9:20 AM</small></div><p>Got it. I’ve checked the layout and left the next item pinned to the plan. The sample material request is attached to the job too.</p></div></div><div class="message"><div class="avatar">G</div><div class="message-body"><div class="message-head"><strong>Garth</strong><small>Today · 9:35 AM · sample</small></div><button class="voice-memo" data-action="memo">${icon('play')}<span class="wave">${'<i></i>'.repeat(18)}</span><small>Walk-through memo · 0:24<br>Read sample transcript</small></button></div></div></div><div class="composer">${icon('clip')}${icon('mic')}<span>Browse-only thread. Posting and recording are locked.</span><button class="btn small" data-action="locked:message sending" aria-label="Message sending is locked in this demo">${icon('lock')}Locked</button></div></section><div class="stack">${panel('A conversation with context',`<p class="body-copy">Photos and notes stay with this project instead of getting lost in a group text. Each task can link back to the place and the conversation.</p><button class="text-btn" data-action="tab:plans" style="margin-top:12px">See the plan pins ${icon('arrow')}</button>`,'message')}${panel('Customer updates',`<p class="body-copy">An “on the way” notification can be part of the live workflow once customer consent and delivery are configured.</p><span class="badge neutral" style="margin-top:15px">Sending locked</span>`,'phone')}</div></div>`;}
const formDefs=[['recommendation','Deferred recommendation','A clear record of the recommendation, the customer’s decision, and supporting photos.','Unsigned example'],['checklist','Installation handover checklist','Example checklist for documentation, walkthrough and close-out.','Sample checklist'],['planfile','Bath layout · Revision B','Illustrative plan with task pins. Revision A is marked superseded.','Current example']];
function forms(j){return `${j?'':heading('A CLEAR RECORD','Forms & files','Job documents, recommendations, access notes and plan revisions.',btn('New form','locked:form creation','','plus'))}${callout('<strong>Preview the workflow.</strong> Sample forms can be read, but not filled, signed or sent. The recommendation example is not an approved legal form.','file')}<div class="two-col"><section class="panel">${formDefs.map(([id,t,d,s])=>`<button class="form-card" data-action="form:${id}:${j?.id||'HP-104'}">${icon(id==='planfile'?'plan':'file')}<div><strong>${t}</strong><p>${d}</p>${badge(s)}</div>${icon('chevron')}</button>`).join('')}</section>${panel('Job essentials, easy to find',`<p class="body-copy">Keep access instructions, site leads and important notes in each job. Contact history connects repeat work to the same customer.</p><button class="text-btn" data-action="${j?'tab:overview':'nav:contacts'}" style="margin-top:14px">${j?'View job essentials':'Explore contacts'} ${icon('arrow')}</button>`,'pin')}</div>`;}
function financials(j){if(state.role!=='owner')return callout('Job costs are available in the owner preview.','lock');const labor=j.hours*laborRate,contribution=j.value-j.materials-labor,margin=j.value?contribution/j.value*100:0;return callout('<strong>Illustrative job economics · QuickBooks is not connected.</strong> Job value is a fictional quote, not cash received. Labor uses a sample loaded cost of $35/hour. Estimated contribution excludes overhead, taxes and any remaining costs.','chart')+`<div class="profit-grid">${[[money(j.value),'Quoted job value','Fictional quote · not collected revenue'],[money(j.materials),'Recorded materials','Sample job purchases'],[money(labor),'Recorded labor',`${j.hours} hours × $35 sample cost`],[money(contribution),'Estimated contribution',`${margin.toFixed(1)}% of quoted value · before overhead`]].map(([v,t,s],i)=>`<div class="profit-card ${i===3?'accent':''}"><small>${t}</small><strong>${v}</strong><p>${s}</p></div>`).join('')}</div><div class="two-col">${panel('Where the job value goes',`<div class="cost-bar" role="img" aria-label="Materials ${money(j.materials)}, labor ${money(labor)}, estimated contribution ${money(contribution)}"><span style="width:${j.materials/j.value*100}%"></span><span style="width:${labor/j.value*100}%"></span><span style="width:${margin}%"></span></div><div class="cost-legend"><span><i style="background:#b89b6d"></i>Materials</span><span><i style="background:#95a983"></i>Labor</span><span><i style="background:#dfe6d4"></i>Contribution</span></div><p class="body-copy" style="margin-top:24px">This view helps you compare the quoted scope with the costs recorded so far. It is not a final profit statement.</p>`,'chart')}${panel('Quote & invoice preview',`<div class="info-row"><span class="label">SAMPLE QUOTE</span><strong>Q-${j.id.slice(3)} · ${money(j.value)}</strong><p>Example record · no invoice has been issued</p></div><div class="info-row"><span class="label">SOURCE OF TRUTH</span><strong>QuickBooks · connection planned</strong><p>Approved import and reconciliation to be configured before launch.</p></div><button class="text-btn" style="margin-top:13px" data-action="invoice:${j.id}">Open sample quote ${icon('arrow')}</button>`,'file')}</div>`;}
function schedule(){const start=state.week===0?26:state.week===1?2:19,month=state.week===1?'November':'October',dates=state.week===0?['2026-10-26','2026-10-27','2026-10-28','2026-10-29','2026-10-30']:state.week===1?['2026-11-02','2026-11-03','2026-11-04','2026-11-05','2026-11-06']:['2026-10-19','2026-10-20','2026-10-21','2026-10-22','2026-10-23'];return heading('A LITTLE MORE CLARITY','Your schedule','A fixed sample week. Open any job to explore its details.',btn('Schedule work','locked:scheduling','','plus'))+`<div class="week-head"><strong>${month} ${start}–${start+4}, 2026</strong><div class="heading-actions">${btn('Previous','week:-1','small','back')}${btn('Demo week','week:0','small','calendar')}${btn('Next','week:1','small','chevron')}</div></div><div class="week-grid">${dates.map((d,i)=>{const js=visibleJobs().filter(j=>j.date===d);return `<section class="day-col ${d==='2026-10-29'?'today':''}"><div class="day-label"><span>${['MON','TUE','WED','THU','FRI'][i]}</span><strong>${start+i}</strong></div>${js.map(j=>`<button class="schedule-card" data-action="job:${j.id}">${img(j.cover,j.title+' · sample')}<div><small>${j.time}</small><h3>${j.title}</h3><p>${j.crew.join(' & ')} · ${j.town}</p></div></button>`).join('')||'<p class="body-copy" style="text-align:center;font-size:9px">No sample work</p>'}</section>`;}).join('')}</div><p class="image-note" style="margin-top:17px">Tip: on your phone, swipe across the week to see the next day. Scheduling and rescheduling are locked.</p>`;}
const mapPositions=[[66,24],[36,72],[74,38],[37,52],[60,23],[57,19],[45,87]];
function mapPage(){return heading('KNOW YOUR NEXT STOP','Work across the Upstate','Browse project locations and open a job. Sample pins show towns only.')+callout('<strong>Illustrative job map.</strong> Pin locations are approximate and do not identify customer addresses. Real navigation and location tracking are disabled.','map')+`<div class="map-wrap"><section class="map"><svg viewBox="0 0 700 520" preserveAspectRatio="none" aria-hidden="true"><rect width="700" height="520" fill="#e9eddf"/><path d="M0 320C100 290 30 430 100 450S110 520 30 520H0Z" fill="#cbded9"/><g fill="#dee5cf"><path d="M35 70 150 32l50 70-65 98L50 180zM440 55 610 0l90 90-65 110-150-10zM500 360l140-50 60 110-30 100H500zM185 255l90-50 60 80-70 70z"/></g><g fill="none" stroke-linecap="round"><path d="M80 90 315 235 530 280 700 190M315 235 225 520M315 235 480 55" stroke="#fffdf5" stroke-width="13"/><path d="M80 90 315 235 530 280 700 190M315 235 225 520M315 235 480 55" stroke="#d4d8c5" stroke-width="1"/><path d="M0 390 250 350 610 110M130 0l75 190 320 210 175 30M260 80l190 70 160 250" stroke="#f9faf0" stroke-width="5"/></g><g fill="#93a080" font-family="sans-serif" font-size="12"><text x="425" y="97">EASLEY</text><text x="491" y="220">POWDERSVILLE</text><text x="180" y="290">PENDLETON</text><text x="208" y="440">ANDERSON</text><text x="560" y="92">GREENVILLE</text><text x="55" y="455" fill="#8ca7a0" font-size="10">LAKE HARTWELL</text></g></svg>${visibleJobs().filter(j=>j.status!=='Completed').map(j=>{const [x,y]=mapPositions[jobs.indexOf(j)]||[50,50];return `<button class="map-pin" style="left:${x}%;top:${y}%" data-action="route:${j.id}" aria-label="Explore ${j.title}"><span>${jobs.indexOf(j)+1}</span></button>`;}).join('')}<span class="map-note">Illustrative map · approximate towns · not for navigation</span></section><section class="panel panel-pad map-job-list">${visibleJobs().filter(j=>j.status!=='Completed').map((j)=>`<button class="task-row" data-action="job:${j.id}"><span class="task-circle">${jobs.indexOf(j)+1}</span><span class="task-copy"><strong>${j.title}</strong><small>${j.town} · ${j.phase}</small></span>${icon('chevron')}</button>`).join('')}</section></div>`;}
function contacts(){const groups=[...new Set(visibleJobs().map(j=>j.customer))];return heading('PEOPLE, WITH CONTEXT','Contacts & customers','A simple directory with the whole history of the relationship.',btn('Add contact','locked:contact creation','','plus'))+`${state.role==='field'?callout('<strong>Field directory preview.</strong> Project names and site context are visible. Private customer phone numbers, email and financials are hidden.','shield'):''}<div class="contact-grid">${groups.map((c,i)=>{const js=visibleJobs().filter(j=>j.customer===c),j=js[0];return `<button class="contact-card" data-action="contact:${j.id}"><span class="avatar">${c[0]}</span><span class="label">${c.includes('Builders')?'BUILDER':'CUSTOMER'} · SAMPLE</span><h3>${c}</h3><p>${state.role==='owner'?j.contact:j.town+', SC'}<br>${state.role==='owner'?j.phone:'Contact details restricted'}</p><small>${js.length} ${js.length===1?'job':'jobs'} · ${js.filter(x=>x.status!=='Completed').length} open &nbsp; ${icon('arrow')}</small></button>`;}).join('')}</div>`;}
function hours(){const field=state.role==='field',total=field?18:40,data=state.period==='Day'?{labels:['8 AM','9 AM','10 AM','11 AM','1 PM','2 PM','3 PM'],values:field?[1,1,1,0,1,1,1]:[2,2,2,0,1,1,1],total:field?6:9}:state.period==='Month'?{labels:['Week 1','Week 2','Week 3','Week 4'],values:field?[20,24,22,18]:[32,36,38,40],total:field?84:146}:{labels:['Mon','Tue','Wed','Thu','Fri'],values:field?[4,4,4,6,0]:[10,10,11,9,0],total};return heading('TIME WELL SPENT',field?'My hours':'Hours & crew time','Read-only sample time records. No live clock is running.')+`<div class="filters">${['Day','Week','Month'].map(p=>`<button class="chip ${state.period===p?'active':''}" data-action="period:${p}">${p}</button>`).join('')}</div><div class="hours-layout">${panel(`${field?'Eli’s':'Team'} sample ${state.period.toLowerCase()} · ${data.total} h`,`<p class="body-copy">${state.period==='Month'?'October 2026 · sample totals':state.period==='Day'?'Thursday, October 29 · sample hours':'October 26–30, 2026 · sample hours'}</p><div class="bar-chart" role="img" aria-label="${data.labels.map((l,i)=>l+': '+data.values[i]+' hours').join(', ')}">${data.values.map((v,i)=>`<div class="bar-group"><span>${v} h</span><div class="bar ${i===3?'today':''}" style="height:${Math.max(2,v/Math.max(...data.values)*155)}px"></div><small>${data.labels[i]}</small></div>`).join('')}</div>`,'chart')}<section class="panel clock-preview">${icon('clock')}<h3>No clock running.</h3><p>This is a preview of the field time clock.<br>When live, choose a job and confirm your clock-in.</p>${btn('Clock-in locked','locked:clock-in','primary','lock')}<p style="margin-top:12px;font-size:8px">No payroll or time records can be created here.</p></section></div><div style="margin-top:22px" class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Person</th><th>Job</th><th>Demo day</th><th>Week total</th></tr></thead><tbody>${(field?[['Eli','HP-104',6,18]]:[['Garth','HP-105',3,22],['Eli','HP-104',6,18]]).map(([n,id,h,w])=>`<tr><td><strong>${n} · sample</strong></td><td><button data-action="job:${id}">${jobById(id).title}</button></td><td>${h} h</td><td>${w} h</td></tr>`).join('')}</tbody></table></div></div>`;}
function team(){return heading('BUILT TO GROW WITH YOU','Your team','Start with you. Add a crew when you’re ready.',btn('Invite teammate','locked:team invitation','','plus'))+`<div class="two-col">${panel('Workspace roles',`<div class="team-person"><span class="avatar">G</span><div><strong>Garth · owner preview</strong><small>All jobs · costs · customers · team</small></div>${badge('Owner')}</div><div class="team-person"><span class="avatar">E</span><div><strong>Eli · fictional field person</strong><small>Shared projects · assigned service calls · own hours</small></div>${badge('Field')}</div>`,'users')}${panel('Try both sides',`<p class="body-copy">Use the role selector at the top to explore the owner and field experience. The field preview hides money and private customer details.</p><p class="body-copy" style="margin-top:12px">Both roles use fictional data. Real authentication and server-side permissions must be configured before a live workspace is enabled.</p><button class="text-btn" data-action="role:${state.role==='owner'?'field':'owner'}" style="margin-top:14px">Try ${state.role==='owner'?'the field':'the owner'} view ${icon('arrow')}</button>`,'shield')}</div>`;}
function ready(){return heading('WHEN THE WORK STARTS COMING','From a demo to your workspace.','Explore now. Set up a real workspace when the time is right.')+`<section class="hero" style="height:230px">${img('rough-in','Illustrative plumbing progress photo · AI-generated')}<div class="hero-copy"><div class="eyebrow">A WORKSPACE BUILT AROUND YOUR WORK</div><h1 style="font-size:37px">Your craft.<br>A little less admin.</h1><p>Keep the details close. Keep moving forward.</p></div></section><div class="readiness-grid">${[['work','Start with the essentials','Jobs, contacts, photos, plans, to-dos, forms, material requests and your time. Keep the everyday work simple.','Core workflow'],['chart','Connect the business','Configure real sign-in and permissions, review imports, and agree how quotes, costs and QuickBooks should work together.','Live setup required'],['spark','Grow when it helps','Additional crew, customer notifications, receipt recognition, an AI assistant or phone answering can be considered when you need them.','Future options']].map(([ic,t,p,b])=>`<article class="readiness-card">${icon(ic)}<h3>${t}</h3><p>${p}</p>${badge(b)}</article>`).join('')}</div><div class="plan-pricing"><div><h2>No rush. Take a look around.</h2><p>The conversation discussed $150 setup and $100/month for individual use. Team access and additional services would be agreed separately. This demo does not start a subscription.</p></div><strong>$150 <small>setup</small><br>$100 <small>/ month · individual</small></strong></div><div class="two-col" style="margin-top:22px">${panel('Before real work begins',`<p class="body-copy">Confirm branding and scope, create authenticated owner and crew access, configure private file storage and backups, test uploads and time records, and review any accounting, messaging or signature integration. Dummy data stays separate from the live workspace.</p>`,'shield')}${panel('About this demo',`<p class="body-copy">Built from the Collins /Field layout and Garth’s conversation: open work first, visual job records, plans with tasks, contacts, receipts and costs. Heirloom’s logo, green and gold palette, and “Generational Quality” branding come from the business website. Job images are stock or generated illustrations.</p><button class="text-btn" data-action="sources" style="margin-top:12px">View branding & photo sources ${icon('arrow')}</button>`,'info')}</div>`;}

function openModal(title,sub,body,actions='',cls=''){lastFocus=document.activeElement;const d=$('#modal');d.className=cls;d.innerHTML=`<header class="modal-header"><div><h2 id="modal-title">${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;if(!d.open)d.showModal();}
function closeModal(){const d=$('#modal');if(d.open)d.close();gallery=[];if(lastFocus?.isConnected)lastFocus.focus();}
function locked(what='action'){openModal('You’re in the demo.','Browse freely. The real work starts when your workspace is set up.',`${callout(`<strong>${esc(what.charAt(0).toUpperCase()+what.slice(1))} is locked.</strong> No job, customer, time entry, upload, signature, message, invoice or payment can be created here.`,'lock')}<p>You can explore all the sample projects, open photos, view plans and pins, read job conversations, and switch between the owner and field views.</p>`,btn('Keep exploring','close','primary','arrow')+btn('See the launch path','nav:ready','','leaf'));}
function tour(){openModal('Make yourself at home, Garth.','A quick look at what your workspace could feel like.',`<p>Everything here is fictional. Open things, look through the details, and see what would make your day easier.</p><div class="tour-list">${[['job:HP-104','Open a job. All the details, together.'],['job:HP-104:plans','Tap a plan pin. Find the task and photo.'],['receipt:HP-104','Explore a receipt linked to materials.'],['role:field','Try the field view. Keep it simple for the crew.']].map(([a,t],i)=>`<button data-action="${a}"><span class="step-number">${i+1}</span>${t}${icon('arrow')}</button>`).join('')}</div>`,btn('Explore open work','nav:jobs','primary','work'));}
function showTask(id){const t=tasks.find(t=>t.id===id);if(!t||!visibleIds().has(t.job))return;openModal(t.title,`${jobById(t.job).title} · ${t.id} · ${t.area}`,`${badge(t.status)}<p>${t.detail}</p>${img(t.photo,'Illustrative task photo','modal-image')}<span class="label">SAMPLE IMAGE · NOT HEIRLOOM JOB EVIDENCE</span><h3>Task conversation · sample</h3><p><strong>${t.who}</strong> · ${t.when}<br>Keeping this note and photo connected to the plan, so the next person has the context.</p>`,btn('Open job conversation',`job:${t.job}:notes`,'primary','message')+btn('Change status · locked','locked:task changes','','lock'));}
function openGallery(id){gallery=(state.page==='job'?jobPhotos(state.job):visiblePhotos());galleryIndex=Math.max(0,gallery.findIndex(p=>p.id===id));showGallery();}
function showGallery(){const p=gallery[galleryIndex];if(!p)return;lastFocus=document.activeElement;const d=$('#modal');d.className='gallery-modal';d.innerHTML=`<header class="modal-header"><div><h2 id="modal-title">${p.caption}</h2><p>${jobById(p.job).title} · ${galleryIndex+1} of ${gallery.length}</p></div><button class="icon-btn" data-action="close" aria-label="Close photo">${icon('close')}</button></header><div class="gallery-stage" id="gallery-stage">${img(p.file,p.caption+' · '+p.source,'',true)}<button class="gallery-arrow prev" data-action="gallery:-1" aria-label="Previous photo">${icon('back')}</button><button class="gallery-arrow next" data-action="gallery:1" aria-label="Next photo">${icon('chevron')}</button></div><div class="gallery-caption"><span>${p.by} · ${p.date}, 2026 · ${p.stage}<br>${p.source} · illustrative sample, not Heirloom job evidence</span><span>Swipe or use ← → to browse</span></div>`;if(!d.open)d.showModal();let x=0,y=0;$('#gallery-stage').addEventListener('touchstart',e=>{x=e.changedTouches[0].clientX;y=e.changedTouches[0].clientY;},{passive:true});$('#gallery-stage').addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-x,dy=e.changedTouches[0].clientY-y;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)){galleryIndex=(galleryIndex+(dx<0?1:-1)+gallery.length)%gallery.length;showGallery();}},{passive:true});}
function receipt(id){const j=jobById(id)||jobs[0];const owner=state.role==='owner';openModal('A photo becomes a material record.','Prefilled example · no upload, OCR or QuickBooks connection',`${callout('<strong>This is a simulation.</strong> The receipt below is a typeset fictional source example. No image was scanned. Values are fixed fixtures; tax is assumed $0 for this example only.','receipt')}<div class="receipt-preview"><div><div class="receipt"><h3>SAMPLE SUPPLY CO.</h3><div>DEMO RECEIPT<span>10/29/26</span></div><hr><div>PEX 100 FT × 2<span>${owner?'85.00':'—'}</span></div><div>FITTINGS × 10<span>${owner?'87.50':'—'}</span></div><div>SHOWER VALVE<span>${owner?'185.00':'—'}</span></div><hr><div>SUBTOTAL<span>${owner?'357.50':'—'}</span></div><div>DEMO TAX<span>${owner?'0.00':'—'}</span></div><div>TOTAL<span>${owner?'357.50':'—'}</span></div><small>FICTIONAL SOURCE EXAMPLE<br>NOT A PURCHASE OR PROOF OF PAYMENT</small></div><p class="receipt-label">Original source stays linked for review.</p></div><div><h3 style="margin-top:0">Example extracted lines</h3>${materialLines.slice(0,3).map(l=>`<div class="info-row"><span class="label">QUANTITY ${l.qty}</span><strong>${l.name}</strong>${owner?`<p>${money(l.unit)} each · ${money(l.qty*l.unit)} total</p>`:''}</div>`).join('')}<h3>Review before adding</h3><p>The live flow would require you to confirm the item, quantity, price and job. The source photo would remain attached.</p><span class="badge neutral" style="margin-top:16px">Example tied to HP-104 only</span></div></div>`,btn('View sample materials','job:HP-104:materials','primary','box')+btn('Add to job · locked','locked:receipt import','','lock'));}
function showForm(type,id){const j=jobById(id)||jobs[0];if(type==='planfile'){go('job',j.id,'plans');return;}const recommendation=type==='recommendation';openModal(recommendation?'Deferred recommendation':'Installation handover checklist',`${j.title} · Read-only sample · Unsigned`,recommendation?`<div class="document"><span class="label">HEIRLOOM PLUMBING LLC · DRAFT WORKFLOW EXAMPLE</span><h3>Recommendation & customer decision</h3><p><strong>Job:</strong> ${j.id} · ${j.title}<br><strong>Customer:</strong> ${j.customer} · fictional</p><h3>Recommended work</h3><p>Review an optional shutoff access improvement with the homeowner before closing the wall. Attach the recommendation, scope and supporting photos to the job.</p><h3>Customer decision · sample</h3><p>Customer requests that the optional improvement be discussed at a later date. This example documents a conversation only and does not release liability.</p><div class="signature">Signature unavailable in demo</div><p style="margin-top:13px">Unsigned draft · not an approved legal agreement. Any live legal form requires appropriate review before use.</p></div>`:`<div class="document"><span class="label">SAMPLE CHECKLIST · NO STATUS CHANGES</span><h3>A clean handover.</h3>${['Work scope reviewed with customer','Progress and finish photos filed','Equipment documentation attached','Customer walkthrough recorded','Open punch items reviewed'].map((t,i)=>`<div class="task-row"><span class="task-circle ${i<3?'done':''}">${i<3?icon('check'):''}</span><span class="task-copy"><strong>${t}</strong><small>${i<3?'Sample completed item':'Sample pending item'}</small></span></div>`).join('')}</div>`,btn('Sign or send · locked','locked:form signing','','lock')+btn('Back to workspace','close','primary','arrow'));}
function contact(id){const j=jobById(id),history=visibleJobs().filter(x=>x.customer===j.customer);openModal(j.customer,'Fictional customer profile · linked job history',`${state.role==='owner'?`<div class="info-row"><span class="label">CONTACT · SAMPLE DETAILS</span><strong>${j.contact}</strong><p>${j.phone} · ${j.email}</p></div>`:callout('Phone, email and financial details are hidden in this field preview.','lock')}<h3>Job history</h3>${history.map(x=>`<button class="task-row" data-action="job:${x.id}">${img(x.cover,'Illustrative job photo','task-thumb')}<span class="task-copy"><strong>${x.title}</strong><small>${x.id} · ${x.phase}</small></span>${badge(x.status)}</button>`).join('')}`,btn('Contact customer · locked','locked:customer communication','','lock'));}
function route(id){const j=jobById(id);openModal('Your next stop, in context.',`${j.title} · Approximate town only`,`${img(j.cover,'Illustrative sample project','modal-image')}<div class="info-row"><span class="label">SAMPLE DESTINATION</span><strong>${j.address} · ${j.town}, SC</strong><p>This is a fictional street address. No navigation will be launched.</p></div><div class="info-row"><span class="label">ACCESS NOTES · FICTIONAL</span><strong>${j.access}</strong></div>`,btn('Open job',`job:${id}`,'primary','work')+btn('Navigation · locked','locked:real navigation','','lock'));}
function invoice(id){const j=jobById(id);if(state.role!=='owner'){locked('financial access');return;}openModal('Sample quote preview',`${j.id} · Fictional quote · Never issued`, `<div class="document"><span class="label">HEIRLOOM PLUMBING LLC · SAMPLE ONLY</span><h3>Quote Q-${id.slice(3)}</h3><p>Prepared for ${j.customer} · fictional<br>${j.address} · ${j.town}, SC</p><div class="info-row"><strong>${j.title}</strong><p>${j.description}</p></div><div class="info-row"><span class="label">SAMPLE QUOTED VALUE</span><strong>${money(j.value)}</strong><p>Tax not calculated · terms not agreed · no payment requested</p></div><p style="margin-top:20px">This is a fixed presentation example. It is not a customer quote, invoice, QuickBooks record or payment request.</p></div>`,btn('Send or collect · locked','locked:quote sending and payment collection','','lock')+btn('Back to job','close','primary','arrow'));}
function search(q){q=String(q||'').trim();if(!q)return;const list=visibleJobs().filter(j=>`${j.title} ${j.id} ${j.customer} ${j.town} ${j.type}`.toLowerCase().includes(q.toLowerCase()));openModal('Search the sample workspace',`Results for “${esc(q)}”`,list.length?`<div class="search-results">${list.map(j=>`<button data-action="job:${j.id}">${img(j.cover,'Sample job photo')}<span><strong>${j.title}</strong><small>${j.id} · ${j.customer} · ${j.town}</small></span>${icon('chevron')}</button>`).join('')}</div>`:'<p>No matching sample jobs. Try “Oakridge,” “Morgan,” “Easley” or a job number.</p>');}
function activity(){openModal('A little progress, all together.','Fictional recent activity',`<div class="timeline-row"><span class="timeline-dot"></span><div class="timeline-content"><small>9:35 AM · sample</small><h4>Garth left a walkthrough memo</h4><p>Oakridge · Primary bath</p></div></div><div class="timeline-row"><span class="timeline-dot"></span><div class="timeline-content"><small>9:20 AM · sample</small><h4>Eli requested two shutoff valves</h4><p>Material request · Oakridge</p></div></div><div class="timeline-row"><span class="timeline-dot"></span><div class="timeline-content"><small>8:45 AM · sample</small><h4>Wall documentation task completed</h4><p>Photo linked to plan pin 3</p></div></div>`,btn('Open Oakridge','job:HP-104','primary','work'));}
function sources(){openModal('Built for Heirloom.','Brand references and illustrative imagery',`<p>Business branding, logo and brand graphics: <a href="https://www.heirloomplumb.com/" target="_blank" rel="noopener noreferrer" style="text-decoration:underline">Heirloom Plumbing website</a> and <a href="https://www.heirloomplumb.com/about" target="_blank" rel="noopener noreferrer" style="text-decoration:underline">About page</a>. The About page identifies Garth George as the owner and Master Plumber. The supplied Facebook announcement was not accessible during research.</p><h3>Illustrative job images</h3><p>Stock interiors and exteriors from Unsplash. Three plumbing scenes were created with the built-in image generation tool. All job imagery is marked as sample content and does not represent Heirloom project documentation.</p><h3>Demo boundary</h3><p>No customer records, private photos, logins, APIs, accounting accounts or data from Collins Electric are included. The design and navigation use Collins /Field as the workflow reference.</p>`);}
function more(){openModal('Your workspace','Explore the rest of the demo',`<div class="mobile-menu">${navs.filter(n=>!['home','jobs','schedule','photos'].includes(n[0])).map(([id,ic,n])=>`<button data-action="nav:${id}">${icon(ic)}${n}</button>`).join('')}<button data-action="nav:ready">${icon('leaf')}When you’re ready</button><button data-action="tour">${icon('info')}Quick tour</button></div>`);}
function toast(s){const t=$('#toast');clearTimeout(toastTimer);t.textContent=s;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),4500);}
function go(page,job=null,tab='overview'){closeModal();state.page=page;state.job=job;state.tab=tab;state.photoFilter='All photos';state.taskFilter='All tasks';state.zoom=1;const hash=page==='job'?`job/${job}/${tab}`:page;if(location.hash.slice(1)!==hash)location.hash=hash;else render();window.scrollTo({top:0,behavior:'instant'});}
function readHash(){const [p,id,tab]=location.hash.slice(1).split('/');if(p==='job'&&visibleJobs().some(j=>j.id===id)){state.page='job';state.job=id;state.tab=tab||'overview';if(state.role==='field'&&state.tab==='financials')state.tab='overview';}else{state.page=[...navs.map(n=>n[0]),'ready'].includes(p)?p:'home';state.job=null;}render();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const [a,b,c]=el.dataset.action.split(':');switch(a){case'nav':go(b);break;case'job':go('job',b,c||'overview');break;case'tab':state.tab=b;state.taskFilter='All tasks';state.photoFilter='All photos';state.zoom=1;go('job',state.job,b);break;case'filter':state.filter=b;render();break;case'view':state.view=b;render();break;case'photofilter':state.photoFilter=b;render();break;case'taskfilter':state.taskFilter=b;render();break;case'task':showTask(b);break;case'photo':openGallery(b);break;case'gallery':galleryIndex=(galleryIndex+Number(b)+gallery.length)%gallery.length;showGallery();break;case'close':closeModal();break;case'locked':locked(b);break;case'tour':tour();break;case'receipt':receipt(b);break;case'form':showForm(b,c);break;case'route':route(b);break;case'contact':contact(b);break;case'invoice':invoice(b);break;case'period':state.period=b;render();break;case'week':state.week=b==='0'?0:Math.max(-1,Math.min(1,state.week+Number(b)));render();break;case'zoom':state.zoom=Math.max(.8,Math.min(1.8,state.zoom+Number(b)*.2));applyZoom();break;case'activity':activity();break;case'more':more();break;case'role':state.role=b;closeModal();if(b==='field'&&state.tab==='financials')state.tab='overview';render();toast(b==='field'?'Field preview: Eli’s work and own hours. Costs and private customer contacts are hidden.':'Owner preview: the whole workspace.');break;case'memo':openModal('Walk-through memo','Fictional transcript preview · 24-second example',`<p>“Walk-through note for the primary bath. Keep a photo of each open wall before close-up. The builder needs to confirm the vanity centerline. I’ve left the reminder pinned on the plan so we can find it when we come back.”</p><h3>Transcript only</h3><p>This is sample text. No audio has been recorded, uploaded or transcribed.</p>`);break;case'sources':sources();break;}});
document.addEventListener('keydown',e=>{if($('#modal').open&&gallery.length&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();galleryIndex=(galleryIndex+(e.key==='ArrowRight'?1:-1)+gallery.length)%gallery.length;showGallery();}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#modal').addEventListener('close',()=>{gallery=[];});
window.addEventListener('hashchange',()=>{closeModal();readHash();});
readHash();
